const tiket = [
  {judul: 'Link A', selesai: false},
  {judul: 'Link B', selesai: true},
];
function hitungAktif(items) {
  return items.filter(item => !item.selesai).length;
}
console.log('Aktif:', hitungAktif(tiket));
for (const item of tiket) {
  console.log(`${item.judul}: ${item.selesai ? 'selesai' : 'aktif'}`);
}
